<?php
require_once __DIR__.'/bootstrap.php';
$s=current_settings();$error='';$ok='';
if(isset($_GET['logout'])){unset($_SESSION['public_ok']);header('Location:public_activation.php');exit;}
if(!empty($s['public_password_hash']) && empty($_SESSION['public_ok'])){
 if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['gate_password'])){if(password_verify((string)$_POST['gate_password'],(string)$s['public_password_hash'])){$_SESSION['public_ok']=1;header('Location:public_activation.php');exit;}else $error='Senha de acesso inválida.';}
 ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ativação • Akira</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="public-wrap"><div class="auth-card"><img src="assets/akira-brand.png"><h1>Ativação Akira</h1><p>Digite a senha definida pelo administrador.</p><?php if($error):?><div class="notice"><?=h($error)?></div><?php endif?><form method="post" class="stack"><label>Senha<input type="password" name="gate_password" required></label><button class="btn">Continuar</button></form></div></div></body></html><?php exit;
}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_activation'])){$device=trim((string)$_POST['device_id']);$server=(int)$_POST['server_id'];$name=trim((string)$_POST['list_name']);$u=(string)$_POST['username'];$p=(string)$_POST['password'];if($device&&$server&&$u&&$p){$existing=db()->prepare('SELECT id FROM activations WHERE device_id=? AND is_primary=1 LIMIT 1');$existing->execute([$device]);$id=$existing->fetchColumn();if($id){db()->prepare('UPDATE activations SET server_id=?,list_name=?,username_enc=?,password_enc=?,is_active=1,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$server,$name?:'Principal',encrypt_secret($u),encrypt_secret($p),$id]);}else{db()->prepare('INSERT INTO activations(device_id,server_id,list_name,username_enc,password_enc,is_primary) VALUES(?,?,?,?,?,1)')->execute([$device,$server,$name?:'Principal',encrypt_secret($u),encrypt_secret($p)]);} $ok='Dados salvos. Volte ao aplicativo e atualize a ativação.';}else $error='Preencha todos os campos obrigatórios.';}
$servers=db()->query('SELECT * FROM servers WHERE is_active=1 ORDER BY name')->fetchAll();
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ativação • Akira</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="public-wrap"><div class="auth-card" style="width:min(680px,100%)"><img src="assets/akira-brand.png"><h1>Ativação pública</h1><p>Cadastre ou atualize a lista principal vinculada ao ID exibido no aplicativo.</p><?php if($ok):?><div class="flash"><?=h($ok)?></div><?php endif?><?php if($error):?><div class="notice"><?=h($error)?></div><?php endif?><?php if(!$servers):?><div class="notice">Nenhum servidor está disponível. O administrador precisa cadastrar um DNS primeiro.</div><?php else:?><form method="post" class="stack"><input type="hidden" name="save_activation" value="1"><div class="form-grid"><label>ID do dispositivo<input name="device_id" required placeholder="A1B2-C3D4-E5F6"></label><label>Servidor<select name="server_id"><?php foreach($servers as $sv):?><option value="<?=$sv['id']?>"><?=h($sv['name'])?></option><?php endforeach?></select></label><label>Nome da lista<input name="list_name" value="Principal"></label><label>Usuário<input name="username" required></label><label>Senha<input type="password" name="password" required></label></div><button class="btn">Salvar ativação</button></form><?php endif?><p class="muted">Se esta página estiver protegida, o acesso é liberado somente após a senha pública definida no painel.</p></div></div></body></html>
